Translate("ruRU", "darnassus", {
	title = "Дарнасс",
	sections = {
		{
			title = "Обзор",
			text = [=[Дарнасс — столица {link:night-elves}ночных эльфов{/link}, город живого дерева и воды, залитой лунным светом, в высоких ветвях {link:teldrassil}Тельдрассила{/link}. Его чертоги не построены, а выращены. Его террасы выходят к садам и тихим прудам, а в сердце его сияет {link:temple-of-the-moon}Храм Луны{/link}. Это молодой город древнего народа. Калдореи возвели его после {link:third-war}Третьей войны{/link}, когда утратили бессмертие, а их старый дом на {link:mount-hyjal}горе Хиджал{/link} лежал израненным, и задумали его как новое начало.]=],
		},
