	sections = {
		{
			title = "Обзор",
			text = [=[Анклав Кенария — квартал друидов на севере {link:darnassus}Дарнасс{/link}а. Здесь растет {link:ogres}огр{/link}омное дерево, где живет {link:fandral-staghelm}верховный друид Фэндрал Олений Шлем{/link}; в нем он изучает беды {link:teldrassil}Тельдрассил{/link}а, а этажом ниже находится его помощник {link:mathrengyl-bearwalker}Матренгил Медвежья Поступь{/link}. По тропам анклава ходят друиды, такие как {link:rellian-greenspyre}Реллиан Зеленый Шпиль{/link}. Охотники и разбойники тоже держат здесь свои залы. За деревом верховного друида кучи странной почвы из дальних земель ждут разбора, а туннели уходят вниз, в глубины под Анклавом.]=],
