			text = [=[Тиранда — живая связь между {link:night-elves}калдореи{/link} былых времен и калдореи нынешних. Она сражалась в {link:war-of-the-ancients}Войне древних{/link} и в {link:third-war}Третьей войне{/link}. При ней {link:sentinels}Часовые{/link} стали щитом своего народа, и при ней ночные эльфы вступили в {link:alliance}Альянс{/link}.]=],
