})

Translate("ruRU", "fandral-staghelm", {
	title = "Фэндрал Олений Шлем",
	subtitle = "Верховный друид Дарнасса",
	found = "Его дерево в Анклаве Кенария",
	hint = "Отыщите верховного друида в его дереве в Анклаве Кенария.",
	allegiance = "Ночные эльфы · Круг Кенария",
	aliases = { "Фэндрал", "верховный друид Фэндрал Олений Шлем" },
	sections = {
		{
			title = "Обзор",
			text = [=[Фэндрал Олений Шлем — верховный друид ночных эльфов. Когда после {link:third-war}Третьей войны{/link} исчез {link:malfurion-stormrage}Малфурион Ярость Бури{/link}, Фэндрал взял на себя главенство над друидами и решил, что его народ отстроится заново. Он вырастил {link:teldrassil}Тельдрассил{/link}, новое Древо Жизни, и по сей день трудится, чтобы сделать его здоровым. Он горд, нетерпелив и неутомим и никому, кроме себя, не доверяет завершить этот труд.]=],
		},
		{
			title = "Значение",
			text = [=[Немногие {link:night-elves}калдореи{/link} повлияли на нынешнюю эпоху сильнее, чем Фэндрал. {link:darnassus}Дарнасс{/link} стоит на дереве, которое он вырастил. Но дерево это с изъяном, бессмертие, которого он искал, не вернулось, а его ссора с Лунной поляной раскалывает {link:cenarion-circle}Круг Кенария{/link}.]=],
		},
		{
			title = "История",
			text = [=[После {link:battle-of-mount-hyjal}битвы у горы Хиджал{/link} {link:nordrassil}Нордрассил{/link} дымился, а друиды остались без предводителя. Фэндрал убедил {link:krueg-skullsplitter}Круг{/link} Древних на {link:darkshore}Темных берегах{/link}, что {link:night-elves}калдореи{/link} должны отстроиться и вернуть себе бессмертие. С одобрения Круга он и самые могучие друиды вырастили {link:teldrassil}Тельдрассил{/link} у северного побережья. Затем он попросил у драконов благословения. Ноздорму отказал ему и укорил за высокомерие, отказала и {link:alexstrasza}Алекстраза{/link}. Без их даров дерево выросло ущербным и непредсказуемым.]=],
		},
		{
			title = "Наши дни",
			text = [=[Фэндрал без отдыха трудится над бедами дерева и называет их ярмом, от которого хотел бы избавиться. Он считает, что он один вывел свой народ из тьмы, а слова Лунной поляны называет пропагандой. Он и {link:keeper-remulos}Хранитель Ремулос{/link} подозревают друг друга. Даже его собственный помощник признает, что воздух между ними густ от недоверия.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он вырастил {link:teldrassil}Тельдрассил{/link}, новое Древо Жизни.
• Он изучает почвы {link:un-goro-crater}Ун'Горо{/link} и завтрашнее зерно.
• Он шлет послания в {link:darkshore}Темные берега{/link}, где живет {link:onu}Ону{/link}, Древо знаний.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О жизни верховного друида до Третьей войны написано мало. Эта запись хранит лишь его деяния после нее.]=],
		},
	},
	chapters = {
		{
			title = "Венец земли",
			hint = [=[Принесите верховному друиду воду лунных колодцев Тельдрассила.]=],
			text = [=[Сосуд, наполненный из лунных колодцев дерева, наконец попал к верховному друиду. Фэндрал проворчал, что это заняло слишком много времени и что гонцы не из самых надежных. Потом он заговорил о том, как тяжко лежат на его плечах беды {link:teldrassil}Тельдрассил{/link}а.]=],
		},
		{
			title = "Донесение оракула",
			hint = [=[Доставьте верховному друиду донесение, которое передало Древо-оракул.]=],
			text = [=[Древо-оракул долго молчало. Его донесение сообщило верховному друиду, что одни недуги дерева ослабли, а другие усилились. Фэндрал вслух посетовал, что его труд, быть может, никогда не будет окончен.]=],
		},
