Translate("ruRU", "sentinels", {
	title = "Часовые",
	sections = {
		{
			title = "Обзор",
			text = [=[Часовые — воины {link:night-elves}ночных эльфов{/link}. Тысячи лет они охраняют леса {link:kalimdor}Калимдора{/link} и подчиняются верховной жрице Элуны. Большинство из них женщины, охотницы, которые владеют дарами богини не хуже, чем глефой и луком.]=],
		},
		{
			title = "Истоки",
			text = [=[После {link:great-sundering}Великого Раскола{/link}, пока друиды спали в {link:emerald-dream}Изумрудном Сне{/link}, жрицы Элуны и их воительницы стерегли {link:night-elves}калдореи{/link}. За эти долгие века Часовые стали щитом своего народа.]=],
		},
		{
			title = "Наши дни",
			text = [=[Часовые несут стражу в каждой деревне {link:teldrassil}Тельдрассил{/link}а и на каждой дороге. Они охраняют Древо-оракул, носят его послания в {link:darnassus}Дарнасс{/link} и сражаются с {link:furbolgs}фурболг{/link}ами Кривой Сосны и {link:harpies}гарпия{/link}ми. За пределами дерева они держат посты на Темных берегах, в Ясеневом лесу и в {link:feralas}Фералас{/link}е. Генерал {link:feathermoon-stronghold}Оперенная Луна{/link} следит, чтобы у каждой из них было время для молитвы, а в Дарнассе они наблюдают за самим городом, ибо опасаются, что там что-то неладно.]=],
		},
	},
})
